#include <iostream>
#include <string>
/* Function Objective: Print one line of the grade report
   Input parameters : str_student_name (string) student name, f_gpax (float) GPAX value
   Function description: Shorten a long name to the maximum length, then print the name and the GPAX
   Return Value : void
   Created By : Programmer A
   Create Date: 2026-09-28
   Revised By:
   Revised Date:
*/
void Print_Report(std::string str_student_name, float f_gpax) {
    const int maxNameLength = 30;
    bool bln_Is_Name_Long = str_student_name.length() > maxNameLength;
    // check whether the name must be shortened
    if (bln_Is_Name_Long) {
        std::cout << str_student_name.substr(0, maxNameLength) << " " << f_gpax << std::endl;
    }
    // else the name fits on one line
    else {
        std::cout << str_student_name << " " << f_gpax << std::endl;
    }
}
